/* Presentation preferences are separate from portable campaign records. */
(()=>{
const key='arydia-ui-v38',fallback={language:'zh',appearance:'light',themeColor:'original',scale:1,skipLanguage:false,skipAbout:false};
let prefs={...fallback};try{const p=JSON.parse(localStorage.getItem(key)||'{}');for(const k of Object.keys(fallback))if(typeof p[k]===typeof fallback[k])prefs[k]=p[k];}catch(_){}
if(!['zh','en'].includes(prefs.language))prefs.language='zh';if(!['light','dark','system'].includes(prefs.appearance))prefs.appearance='light';if(![1,1.1,1.2,1.3].includes(prefs.scale))prefs.scale=1;
const dictionary=Object.assign({},window.UI_EN,{'装备':'Equipped','旅伴':'Characters','新旅伴':'New character','让旅途，轻松一些。':'Make your journey a little easier.','外观与语言':'Appearance & language','外观':'Appearance','语言':'Language','浅色':'Light','深色':'Dark','跟随系统':'System','关于这个软件':'About this app','继续':'Continue','下次不再提醒':"Don’t show this again",'关闭':'Close','选择音乐':'Choose music','音乐设置':'Music settings','道途记录':'Skill tree','道途层次':'Path rank','编辑角色':'Edit character','删除角色':'Delete character','切换或新增角色':'Switch or add character','设置':'Settings','等级':'Level','经验费用':'XP cost','核心属性 · 每级勾选一项':'Core · Choose one per level','基础属性 · 每级勾选一项':'Base · Choose one per level','没有先决技能':'No prerequisites','先决技能':'Prerequisite skills','需要先学会所有先决技能，无需先精通或装备。':'Learn all prerequisite skills first. Mastery or equipment is not required.','全部角色':'All characters','支持英文和中文编号检索。':'Search by card ID or title.','3.8.0 · 网页版':'3.8.0 · Web','设计与制作':'Created by','先决技能：':'Prerequisite skills: ','请先取消后续技能：':'Unlearn these dependent skills first: ','暂无前置关联。':'No previous links recorded.','暂无后续关联。':'No next links recorded.','角色、技能、笔记和收藏保存在本机。换设备、移除桌面版或清理网站数据前，请导出备份。':'Records are stored in this browser. Export a backup before changing devices or clearing website data.','修改后自动保存':'Changes are saved automatically','正在载入…':'Loading…','选择道途':'Choose a path','选择肖像':'Choose a portrait','角色名字（选填）':'Character name (optional)','留空使用种族与道途命名':'Leave blank to use race and path','清空搜索':'Clear search','搜索索引':'Search the index','如：互动1 / POI-1':'e.g. POI-1','点击示例即可检索。':'Tap an example to search.','网页版与离线':'Web app & offline','角色与检索已可离线使用':'Characters and search are available offline','正在准备离线页面…':'Preparing offline pages…','下载离线音乐':'Download offline music','音乐已全部下载，可离线播放。':'All tracks are available offline.','音乐已下载':'Music downloaded','正在下载…':'Downloading…','更新网页版':'Update web app','使用说明':'Help','添加到主屏幕':'Add to home screen','记录保存在当前设备，不会自动同步。清理网站数据或更换设备前，请导出备份。':'Records stay on this device and are not automatically synced. Export a backup before clearing website data or changing devices.','音量请使用 iPhone / iPad 的音量键调节。':'Use the volume buttons on your iPhone or iPad.','保存':'Save','清除':'Clear','事件':'Event','生命':'HP','法力':'MP','体力':'SP','力量':'STR','敏捷':'DEX','智力':'INT','感知':'WIS','魅力':'CHA','耐力':'END'});
const chunks=Object.keys(dictionary).filter(k=>/[\u3400-\u9fff]/.test(k)).sort((a,b)=>b.length-a.length);
function tr(text){text=String(text??'');if(prefs.language!=='en')return text;const trim=text.trim();if(dictionary[trim])return text.replace(trim,dictionary[trim]);
 if(/^\d+ 级$/.test(trim))return 'Level '+trim.match(/\d+/)[0];
 if(/^请按顺序提升等级/.test(trim))return 'Advance one level at a time. Next level: '+trim.match(/\d+/)?.[0];
 if(/^需要达到/.test(trim)) {const n=trim.match(/\d+/g);return `Requires level ${n[0]} (current level ${n[1]}).`;}
 if(/^达到\d+级后/.test(trim))return 'Requires level '+trim.match(/\d+/)[0];
 if(/^请先取消第/.test(trim))return 'Clear attribute marks in level '+trim.match(/\d+/)[0]+' before lowering your level.';
 if(/^已下载 \d+/.test(trim))return trim.replace(/已下载 (\d+\/\d+) 首；全部约 25 MB。/,'Downloaded $1 tracks; about 25 MB total.');
 if(/^\d+ 条结果/.test(trim))return trim.replace('条结果','results');
 return text.replace(new RegExp(chunks.map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|'),'g'),s=>dictionary[s]);
}
const raceColors={human:'#346b85',elf:'#287f76',halfling:'#567936',dwarf:'#576378',moon:'#704a87',orc:'#95463f',cat:'#787522',stone:'#956329',crimson:'#91447d'};
let currentRace='';
const rgb=hex=>hex.replace('#','').match(/../g).map(x=>parseInt(x,16));
const mix=(a,b,t)=>'#'+rgb(a).map((v,i)=>Math.floor(v*(1-t)+rgb(b)[i]*t).toString(16).padStart(2,'0')).join('');
function palette(dark){const accent=prefs.themeColor==='race'?raceColors[currentRace]:null,tone=(a,b)=>dark?b:a,themed=(a,b,l,d)=>accent?mix(tone(a,b),accent,dark?d:l):tone(a,b);const values={paper:themed('#f8f9f3','#131b17',.035,.06),card:themed('#eff4ea','#202c24',.07,.12),ink:themed('#19352b','#e5ebdf',.1,.08),forest:accent?mix(accent,'#000000',dark?.16:.17):tone('#265440','#315d48'),teal:accent?mix(accent,dark?'#ffffff':'#000000',dark?.66:.18):tone('#265440','#b3d8bc'),muted:tone('#5e6d60','#aab8aa'),line:themed('#d3ded1','#3c4d40',.13,.2),sage:themed('#e4ecde','#28392d',.13,.22),selected:accent?mix(dark?'#272c29':'#f2f5ec',accent,dark?.48:.3):tone('#cce5b7','#405e42')};for(const [key,value]of Object.entries(values))document.documentElement.style.setProperty('--'+key,value);}
const sources=new WeakMap(),attrs=new WeakMap();
function localize(root=document.body){if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()) {if(node.parentElement?.closest('script,style,input,textarea,[data-user-text],[data-record-text]'))continue;const old=sources.get(node);const source=old&&node.nodeValue===old.output?old.source:node.nodeValue;const output=tr(source);sources.set(node,{source,output});if(node.nodeValue!==output)node.nodeValue=output;}
 root.querySelectorAll?.('[aria-label],[placeholder],[title]').forEach(el=>{if(el.closest('[data-user-text]'))return;let saved=attrs.get(el)||{};for(const attr of ['aria-label','placeholder','title']){if(!el.hasAttribute(attr))continue;const value=el.getAttribute(attr),old=saved[attr],source=old&&value===old.output?old.source:value,output=tr(source);saved[attr]={source,output};if(value!==output)el.setAttribute(attr,output);}attrs.set(el,saved);});
}
function apply(race){if(typeof race==='string')currentRace=race;const dark=prefs.appearance==='dark'||prefs.appearance==='system'&&matchMedia('(prefers-color-scheme: dark)').matches;document.documentElement.dataset.theme=dark?'dark':'light';document.documentElement.style.colorScheme=dark?'dark':'only light';document.querySelector('meta[name=color-scheme]')?.setAttribute('content',dark?'dark':'only light');document.documentElement.lang=prefs.language==='en'?'en':'zh-CN';document.documentElement.style.setProperty('--text-scale',prefs.scale);palette(dark);document.title=prefs.language==='en'?'Arydia Companion':'阿瑞迪亚 · 旅伴';document.querySelector('meta[name="theme-color"]')?.setAttribute('content',dark?'#131b17':'#f8f9f3');localize();}
function set(update){const next={...prefs,...update};localStorage.setItem(key,JSON.stringify(next));prefs=next;apply();}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',apply);
window.UI={get:()=>({...prefs}),set,tr,localize,apply};apply();
let pending=false;new MutationObserver(()=>{if(!pending){pending=true;queueMicrotask(()=>{pending=false;localize();});}}).observe(document.body,{childList:true,subtree:true,characterData:true});
})();
